    Bug 1995822 - Add basic Microsoft Graph login support to OAuth providers. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D270914

diff --git a/mail/app/StaticPrefList.yaml b/mail/app/StaticPrefList.yaml
index b6ec74abd7b..8e800f02cce 100644
--- a/mail/app/StaticPrefList.yaml
+++ b/mail/app/StaticPrefList.yaml
@@ -38,6 +38,12 @@
   value: false
   mirror: once

+# Is Microsoft Graph enabled? This is currently experimental.
+- name: mail.graph.enabled
+  type: bool
+  value: false
+  mirror: always
+
 # Whether the colors from tags should be applied only to the message(s)
 # actually tagged, or also to any collapsed threads which contain tagged
 # messages.
diff --git a/mailnews/base/src/OAuth2Providers.sys.mjs b/mailnews/base/src/OAuth2Providers.sys.mjs
index 643ecc98676..442fd96d998 100644
--- a/mailnews/base/src/OAuth2Providers.sys.mjs
+++ b/mailnews/base/src/OAuth2Providers.sys.mjs
@@ -39,6 +39,12 @@ const EWS_SCOPES = {
   exchange: "https://outlook.office.com/EWS.AccessAsUser.All",
   extra: "offline_access",
 };
+
+const GRAPH_SCOPES = {
+  exchange: "https://graph.microsoft.com/User.Read",
+  graph: "https://graph.microsoft.com/User.Read",
+};
+
 const TBPRO_SCOPES = "openid profile email offline_access";

 /**
@@ -299,6 +305,12 @@ export var OAuth2Providers = {
       return undefined;
     }

+    // Only allow graph scopes if the Graph API support pref is enabled.
+    const graphApiPrefEnabled = Services.prefs.getBoolPref(
+      "mail.graph.enabled",
+      false
+    );
+
     let [issuer, scopes] = details;
     if (
       issuer == "login.microsoftonline.com" &&
@@ -306,7 +318,14 @@ export var OAuth2Providers = {
     ) {
       // Special case for EWS, to avoid asking for the scope when not needed.
       scopes = EWS_SCOPES;
+    } else if (
+      graphApiPrefEnabled &&
+      issuer == "login.microsoftonline.com" &&
+      type == "graph"
+    ) {
+      scopes = GRAPH_SCOPES;
     }
+
     if (typeof scopes == "string") {
       // Scopes not separated into types.
       return { issuer, allScopes: scopes, requiredScopes: scopes };
diff --git a/mailnews/base/test/unit/test_oAuth2Providers.js b/mailnews/base/test/unit/test_oAuth2Providers.js
index 0489aa7a9c3..1a24526477d 100644
--- a/mailnews/base/test/unit/test_oAuth2Providers.js
+++ b/mailnews/base/test/unit/test_oAuth2Providers.js
@@ -146,6 +146,27 @@ add_task(function testMicrosoftHostnameDetails() {
         "https://outlook.office.com/EWS.AccessAsUser.All offline_access",
     }
   );
+
+  // Make sure we don't support Graph API without the experimental pref.
+  Assert.ok(
+    !OAuth2Providers.getHostnameDetails("outlook.office365.com", "graph")
+  );
+
+  Services.prefs.setBoolPref("mail.graph.enabled", true);
+
+  // The `outlook.office365.com` host may need to be changed, especially once
+  // autodiscover is implemented in
+  // https://bugzilla.mozilla.org/show_bug.cgi?id=1995836.
+  Assert.deepEqual(
+    OAuth2Providers.getHostnameDetails("outlook.office365.com", "graph"),
+    {
+      issuer: "login.microsoftonline.com",
+      allScopes: "https://graph.microsoft.com/User.Read",
+      requiredScopes: "https://graph.microsoft.com/User.Read",
+    }
+  );
+
+  Services.prefs.setBoolPref("mail.graph.enabled", false);
 });

